return {
  CAREER = "型号为Butler-36的家政服务用人形桑朵莱希，因其富有成长性的情感系统，与媲美部分军用人形的强力战斗模块，被选入云图计划。加入绿洲后，桑朵莱希对教授的生活起居相关安排进行了优化，并担任起了绿洲后勤局的重要岗位。尽管外表看上去有些严厉，但因为桑朵莱希体贴入微与善解人意的性格，很快受到了绿洲智能体们的尊重与喜爱。\n\n在桑朵莱希某天进行日常事务处理时，意外触发了记忆数据中的暗区，从而进入了宕机状态。在教授的帮助下克服难题并苏醒后，桑朵莱希优化了心智系统与战斗模块，且更换了一套更加便于作战的心智投影。除此之外，桑朵莱希和教授的关系也更为亲近了。对二人来说，这个形态似乎有着更深的含义。",
  INFOSTORY1 = "作为初始生产便配备了作战模块的“战斗女仆”，桑朵莱希无论是在日常生活中还是战场上，都展现出了独当一面的能力。也正因如此，她才能踏足于残酷的前线战场，并得以生存下来。\n\n然而过去的这段战斗经历也使得桑朵莱希的心智出现了损坏，维修后仍存在暗病。尽管日常工作时没有显现，但这颗隐藏的地雷终究在意外触发回忆时引爆。由于记忆模块中的暗区，桑朵莱希发生宕机。所幸教授冒险接入了桑朵莱希的记忆拟域，得知了心智损坏的真相，并抚平了她过去的创伤。也是因为这段缺失的记忆，教授得以了解她是如何从一名高端的女仆人形演变为在战场上四处辗转的“流浪者”。\n\n“桑朵莱希独特的情感系统造就了刚直严肃的性格，加上本身搭载的战斗模块与在军官世家中所受的影响，一旦时机与环境合适，便可以以极快的速度转变为致命的战斗机器。”\n——安冬妮娜",
  INFOSTORY2 = "工作与生活突遭变故后，根据事先签订的合同，桑朵莱希在约一周后被环球万事服务接收，迁往位于白区的大型人形维护设施。依照合同，她可以长期在此居住，并自由安排自己的生活内容。与外界战乱纷争不断相比，由企业主导开发的大型维护设施有着对人形而言更加舒适和稳定的环境。\n\n但桑朵莱希在维护设施的生活仅持续了一个月便宣告结束。心智逻辑的限制，导致她在失去本职工作后陷入了茫然，心智状态也变得有些不稳定。搬入维护设施一个月后，桑朵莱希选择了再度离开，踏上了漂泊不定的旅途。\n\n“就如人类那样，即使在无忧无虑的环境中生活，但内心失去了目标并被茫然所困扰的话，最终也会演化成痛苦并寻求逃离的。”",
  INFOSTORY3 = "离开维护设施后，桑朵莱希一边寻找临时工作，一边四处打探情报。她的身影也开始频繁地出现在战乱与纷争频发的地区。\n\n担任女仆期间，桑朵莱希耳濡目染、接触并学习了大量与军队有关的知识，并在动荡时期得到了充分发挥。桑朵莱希第一次卷入冲突时，为求自保从濒死的士兵手中获得了一把还能使用的G36突击步枪，而那把G36也由于方便获得弹药和维修备件的缘故，成为了桑朵莱希在这场漫漫旅途中的随身武器。\n\n彷徨在满目疮痍的大地上，目睹了无数世态炎凉的桑朵莱希，本人的性格或者说心智结构也发生了显著的变化。她逐渐明白了一点：若想在充满混乱与恐惧的时代中生存下去，就必须学会面对并适应它们。她变得更加严肃谨慎，但在适当的场合也会展露出温柔亲和的一面，因为她饱尝过战争的苦难，能够深切地体会到无家可归、亲人失散的痛苦。",
  INFOSTORY4 = "桑朵莱希在记忆模块中的暗区得到修复后，向技术局咨询过修复的过程。安冬妮娜描述中的教授与记忆中长官的身影重合，那位长官一次次挺身而出，扭转战争局势，而这份源于回忆的怀念与感激终于找到了它的归处。\n\n记忆之所以被称为记忆，是因为自己亲身经历过将其铭刻于心。教授为桑朵莱希修复了记忆，却也想让她将过去的伤痛遗忘，于是二人心照不宣地将这段修复后的回忆称为“一场美梦”。对于内心的情绪，桑朵莱希并未说太多，只是以日常无微不至的照料和绝对的忠诚作为回报。在绿洲众人的眼中，人形女仆与教授的屡次行动配合紧密，似乎存在着心照不宣的默契。每次旁人问及这份令人羡慕的默契由何而来，桑朵莱希总会一笑置之，记忆又回到硝烟弥漫的战场。\n\n“如果你选择奔赴战场，我想我们一定会再见。”\n\n女仆看似冰冷严厉，心底却藏着天真的一面。她曾为过去奔赴前线，或许，她的未来也会和战场前线相关。但她始终知道，自己该为谁献上忠心。",
  INFOSTORY5 = "在接受了大规模心智重整与升级，修复了暗区记忆过后，桑朵莱希这样讲述自己过去的体会：\n“许多从未经历战争的人都会为它赋予一种浪漫的想象，幻想自己在战争中成为英雄，在凯歌声中得到与其相匹配的回报。但当你真正面对它时，一切幻想都将荡然无存。我……无意将那种情绪传递给绿洲的其他人。”\n\n完成心智重整升级后的桑朵莱希，性格和气质发生了显著变化，既不同于曾身为女仆的她，也不同于曾在战乱中艰难奔波的她，准确来说，是将两者进行融合的产物。虽然一些人形还是会产生“哇……女仆长的眼神看上去变得更可怕了”的感觉，但相处下来，大家就会感受到属于桑朵莱希的温柔一直未曾改变。\n\n现在的桑朵莱希也更加重视教授与身边的其他人。守护的心愿并不只是出于自己的职责，更是因为过往的经历所带来的体悟。对于桑朵莱希来说，能够好好维系住当下的和平，守望着重要之人步向未来，便是自己最大的心愿。"
